package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.audit;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="moderation_audit")public class AuditEntryEntity{@Id private UUID id;@Column(nullable=false,length=100)private String action;@Column(name="aggregate_type",nullable=false,length=60)private String aggregateType;@Column(name="aggregate_id",nullable=false,length=120)private String aggregateId;@Column(name="actor_id",length=120)private String actorId;@Column(name="correlation_id",length=120)private String correlationId;@Column(nullable=false,columnDefinition="TEXT")private String details;@Column(name="occurred_at",nullable=false)private Instant occurredAt;public UUID getId(){return id;}public void setId(UUID v){id=v;}public String getAction(){return action;}public void setAction(String v){action=v;}public String getAggregateType(){return aggregateType;}public void setAggregateType(String v){aggregateType=v;}public String getAggregateId(){return aggregateId;}public void setAggregateId(String v){aggregateId=v;}public String getActorId(){return actorId;}public void setActorId(String v){actorId=v;}public String getCorrelationId(){return correlationId;}public void setCorrelationId(String v){correlationId=v;}public String getDetails(){return details;}public void setDetails(String v){details=v;}public Instant getOccurredAt(){return occurredAt;}public void setOccurredAt(Instant v){occurredAt=v;}}
